-- 2026-10-21, the masters' second texts and photos (owner's request of the
-- same day, checked by him): new words and tags for Жавохир, Иброхим,
-- Жамолиддин and Мироншох, every haircut they named as a tag, Салим's tags
-- from his text, no Борода and Чистка лица in anybody's tags, and the first
-- photos of Иброхим, Салим and Жамолиддин (works/<id>/NN.jpg and NN_t.jpg in
-- the master-photos bucket).
begin;

-- Keratin and biozavivka at the owner's price and time, under «Уход». Only
-- Жавохир (1) and Мироншох (6) do them, so every other master who did every
-- service gets the list of the services as it was before these two.
insert into public.booking_services (id, name_ru, name_uz, price_uzs, duration_minutes, category, sort_order, active) values
  ('hair_keratin', 'Кератин для волос', 'Sochga keratin', 300000, 60, 'care', 5, true),
  ('hair_biowave', 'Биозавивка волос', 'Biozavivka (sochni jingalak qilish)', 400000, 60, 'care', 6, true)
on conflict (id) do nothing;
update public.masters
   set online_service_ids = (select array_agg(id order by category, sort_order, id) from public.booking_services
                              where id not in ('hair_keratin', 'hair_biowave'))
 where active and id not in (1, 6) and online_service_ids is null;

update public.masters set experience_years = 7, specialties_ru = array['Low Fade', 'Mid Fade', 'High Fade', 'Classic Taper', 'Textured Crop', 'Side Part', 'Slick Back', 'Кератин', 'Биозавивка']::text[], specialties_uz = array['Low Fade', 'Mid Fade', 'High Fade', 'Classic Taper', 'Textured Crop', 'Side Part', 'Slick Back', 'Keratin', 'Biozavivka']::text[], bio_ru = 'Жавохир специализируется на классических стрижках, креативных fade и индивидуальных образах: подбирает стрижку под форму лица, тип волос и стиль клиента, оформляет бороду. Его принципы — качество, точность, аккуратность и внимание к каждой детали. Также делает кератин и биозавивку волос.', bio_uz = 'Javohir klassik soch turmaklari, kreativ Fade texnikalari va individual uslublarga ixtisoslashgan: soch turmagini mijozning yuz tuzilishi, soch turi va uslubiga mos tanlaydi, soqolga chiroyli shakl beradi. Asosiy tamoyillari — sifat, aniqlik, ozodalik va har bir detalga eʼtibor. Shuningdek, keratin va biozavivka xizmatlarini koʻrsatadi.' where id = 1;
update public.masters set experience_years = 3, specialties_ru = array['Длинные волосы', 'Классические стрижки', 'Кудрявые волосы', 'Смена имиджа']::text[], specialties_uz = array['Uzun soch', 'Klassik soch turmaklari', 'Jingalak soch', 'Imij oʻzgartirish']::text[], bio_ru = 'Иброхим особенно хорошо работает с длинными и кудрявыми волосами, делает классические стрижки. Правильный выбор для тех, кто хочет сменить образ. К каждому клиенту — индивидуальный подход.', bio_uz = 'Ibrohim ayniqsa uzun va jingalak soch bilan zoʻr ishlaydi, klassik soch turmaklarini ham qiladi. Imijini oʻzgartirmoqchi boʻlganlar uchun toʻgʻri tanlov. Har bir mijozga individual yondashadi.' where id = 2;
update public.masters set specialties_ru = array['Классические стрижки', 'Имиджевые стрижки', 'Подбор под форму лица']::text[], specialties_uz = array['Klassik soch turmaklari', 'Imij soch turmaklari', 'Yuz shakliga mos tanlash']::text[] where id = 3;
update public.masters set experience_years = 7, specialties_ru = array['Классические стрижки', 'Современные стрижки', 'Креативные стрижки']::text[], specialties_uz = array['Klassik soch turmaklari', 'Zamonaviy soch turmaklari', 'Kreativ soch turmaklari']::text[], bio_ru = 'Жамолиддин делает классические, современные и креативные стрижки, оформляет бороду и проводит чистку лица. Подбирает стрижку и форму бороды под черты лица и создаёт индивидуальный образ. Главное в его работе — точность и внимание к каждому клиенту.', bio_uz = 'Jamoliddin klassik, zamonaviy va kreativ soch turmaklarini qiladi, soqolga shakl beradi va yuzni tozalaydi. Soch turmagi va soqol shaklini mijozning yuz tuzilishiga qarab tanlab, individual imij yaratadi. Ishidagi asosiy narsa — aniqlik va har bir mijozga eʼtibor.' where id = 4;
update public.masters set experience_years = 3, specialties_ru = array['Taper Fade', 'Low Fade', 'Mid Fade', 'Skin Fade', 'French Crop', 'Кератин', 'Биозавивка']::text[], specialties_uz = array['Taper Fade', 'Low Fade', 'Mid Fade', 'Skin Fade', 'French Crop', 'Keratin', 'Biozavivka']::text[], bio_ru = 'Мироншох специализируется на современных мужских стрижках — taper, low, mid и skin fade, French crop. Следит за трендами и особое внимание уделяет чистым переходам. Также делает кератин и биозавивку волос.', bio_uz = 'Mironshoh zamonaviy erkaklar soch turmaklariga ixtisoslashgan — Taper, Low, Mid va Skin Fade, French Crop. Trendlarni kuzatib boradi va toza oʻtishlarga alohida eʼtibor beradi. Shuningdek, keratin va biozavivka (sochni jingalak qilish) xizmatlarini koʻrsatadi.' where id = 6;
update public.masters set specialties_ru = array['Low Fade', 'High Fade', 'Burst Fade', 'Классические стрижки', 'Mohawk', 'Wolf Cut', 'Mullet', 'Man Bun', 'Man Bob']::text[], specialties_uz = array['Low Fade', 'High Fade', 'Burst Fade', 'Klassik soch turmaklari', 'Mohawk', 'Wolf Cut', 'Mullet', 'Man Bun', 'Man Bob']::text[] where id = 24;
update public.masters set work_photos = '[{"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/01.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/01_t.jpg?v=1", "width": 916, "height": 1440}, {"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/02.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/02_t.jpg?v=1", "width": 957, "height": 1440}, {"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/03.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/03_t.jpg?v=1", "width": 955, "height": 1440}, {"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/04.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/04_t.jpg?v=1", "width": 931, "height": 1440}, {"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/05.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/05_t.jpg?v=1", "width": 930, "height": 1440}, {"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/06.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/2/06_t.jpg?v=1", "width": 1202, "height": 1384}]'::jsonb where id = 2;
update public.masters set work_photos = '[{"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/24/01.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/24/01_t.jpg?v=1", "width": 917, "height": 1440}, {"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/24/02.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/24/02_t.jpg?v=1", "width": 1440, "height": 809}, {"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/24/03.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/24/03_t.jpg?v=1", "width": 937, "height": 1440}]'::jsonb where id = 24;
update public.masters set work_photos = '[{"url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/4/01.jpg?v=1", "thumb_url": "https://ivowbhraaistxvoymxpf.supabase.co/storage/v1/object/public/master-photos/works/4/01_t.jpg?v=1", "width": 956, "height": 1276}]'::jsonb where id = 4;
commit;
select id, name, experience_years, specialties_ru, jsonb_array_length(coalesce(work_photos, '[]'::jsonb)) as works,
       cardinality(online_service_ids) as services
  from public.masters where active order by id;
